import{_ as e,o as a,c as s,a6 as t}from"./chunks/framework.B_q3ZJNF.js";const w=JSON.parse('{"title":"master 与 worker：一个老板一队员工","description":"","frontmatter":{"title":"master 与 worker：一个老板一队员工"},"headers":[],"relativePath":"nginx-internals-course/07-master-workers.md","filePath":"nginx-internals-course/docs/07-master-workers.md"}'),n={name:"nginx-internals-course/07-master-workers.md"};function o(p,r,d,i,l,c){return a(),s("div",null,[...r[0]||(r[0]=[t(`<h1 id="master-与-worker-一个老板一队员工" tabindex="-1">master 与 worker：一个老板一队员工 <a class="header-anchor" href="#master-与-worker-一个老板一队员工" aria-label="Permalink to &quot;master 与 worker：一个老板一队员工&quot;">​</a></h1><p>两个你大概率遇到过、却未必能讲清的问题。第一个：周五发版，你执行 <code>nginx -s reload</code>，老板在群里问「在线用户的下载会断吗」——你凭经验回答「不会」，但心里没底，因为你说不出凭什么。第二个：上周监控显示一个 worker 进程被内核 OOM 杀掉了，可整站无感，流量像水一样滑给了别的 worker，几秒后进程数恢复正常——你知道是那个管理进程干了什么，但不知道具体是什么。这一章把这两个「凭什么」一次讲透。没有代码，全是机制，但讲完之后你能把这两个问题给人讲明白。</p><p>先看全家福。<code>ps</code> 里那群 nginx 进程长这样：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>root     1234  nginx: master process /usr/sbin/nginx</span></span>
<span class="line"><span>www      1235  nginx: worker process</span></span>
<span class="line"><span>www      1236  nginx: worker process</span></span>
<span class="line"><span>www      1237  nginx: worker process</span></span>
<span class="line"><span>www      1238  nginx: worker process</span></span></code></pre></div><p>一个 <strong>master 进程</strong>（老板）——只管不接待：读配置、管员工、收指令，自己不碰任何客户端连接。一群 <strong>worker 进程</strong>（员工）——真正伺候连接的，每个 worker 就是前六章讲的那个「单线程事件循环」，一人一摊、互不打扰。你配置文件里那行 <code>worker_processes auto;</code>，决定的就是招几个员工（auto 通常等于 CPU 核数）。</p><h2 id="为什么是多进程-而不是多线程" tabindex="-1">为什么是多进程，而不是多线程 <a class="header-anchor" href="#为什么是多进程-而不是多线程" aria-label="Permalink to &quot;为什么是多进程，而不是多线程&quot;">​</a></h2><p>第 1 章算过多线程的账：共享内存要加锁，锁竞争拖垮吞吐，一个线程写坏内存全家阵亡。多进程把这两笔账直接抹掉——进程之间内存完全隔离，没有共享就没有锁，你写坏自己的内存只死你自己。隔离还送了一份保险：<strong>worker 崩了，整站活着</strong>。一个 worker 因为恶意请求触发了 bug 段错误退出，损失的是它手里那几条连接；监听端口不在它手里（下一节讲在哪），其他 worker 各干各的，master 察觉后几毫秒内再招一个新人顶上。这就是上周那次「无感事故」的全部机制——没有魔法，只有隔离加替补。</p><p>那为什么不是「每连接一进程」？第 1 章已经埋葬过那个模型——进程数得跟连接数一样多。这里进程数的账不一样：worker 数量跟 CPU 核数走，不跟连接数走。一个核跑一个事件循环，一个事件循环管几千上万条连接——<strong>多进程解决的是「用满多核」，事件循环解决的是「单核管万连」</strong>，两层各管各的，叠起来才是完整答案。</p><p>还有一笔容易忽略的账：多进程让 reload 和升级成为可能。配置换新、二进制换新，本质都是「换掉干活的人」——而人可以一个一个换，机器不能中途换。这个下面细讲。</p><h2 id="老板手里攥着的那部总机" tabindex="-1">老板手里攥着的那部总机 <a class="header-anchor" href="#老板手里攥着的那部总机" aria-label="Permalink to &quot;老板手里攥着的那部总机&quot;">​</a></h2><p>master 有一个关键动作：<strong>监听 socket（第 2 章那部电话机）是 master 创建的</strong>。它在启动时读配置、绑定端口、打开监听 socket，然后才 fork 出一群 worker。fork 的语义是复制进程——于是每个 worker 出生时手里都攥着同一部总机的钥匙（同一个监听文件描述符的副本）。</p><p>新连接来了怎么办？所有 worker 都在盯着同一部总机。早期实现里内核会把「来客了」广播给所有盯梢的 worker：一群 worker 同时惊醒、抢着去接，最后只有一个接到，其余白醒一趟。这个现象叫<strong>惊群</strong>（thundering herd，一窝蜂醒来多数白忙）。惊群浪费不大但烦人，现代内核和 nginx 已经用「只叫醒一个」的机制解决了它。你只需要记住结论：多个 worker 抢同一部总机，内核负责把每个新连接恰好交给一个 worker。谁接了这条连接就归谁管到关闭——连接从生到死只属于一个 worker。这也再次解释了为什么 worker 之间永远不需要锁。</p><p>master 的职责清单到此齐了：读配置、建总机、招 worker、盯生死、收指令。它自己一行业务代码都不跑——老板越闲，系统越稳。</p><h2 id="信号-操作系统给进程的对讲机" tabindex="-1">信号：操作系统给进程的对讲机 <a class="header-anchor" href="#信号-操作系统给进程的对讲机" aria-label="Permalink to &quot;信号：操作系统给进程的对讲机&quot;">​</a></h2><p>master 怎么「收指令」？进程之间不能直接调用对方的函数——各自的内存空间互相看不见。操作系统为此提供了一条官方通道：<strong>信号</strong>（signal）——发给进程的对讲机暗号，一行命令就能喊：<code>kill -HUP 1234</code> 就是「给 1234 号进程发 HUP 暗号」。nginx 给这些暗号定了含义：</p><table tabindex="0"><thead><tr><th>暗号</th><th>含义</th><th>谁收</th></tr></thead><tbody><tr><td>TERM / QUIT</td><td>立即退出 / 优雅退出（QUIT：送完手头的客人再走）</td><td>worker 或 master</td></tr><tr><td>HUP</td><td>重新读配置（reload）</td><td>master</td></tr><tr><td>USR2</td><td>热升级：启动新二进制</td><td>master</td></tr><tr><td>WINCH</td><td>让旧 worker 优雅退休（配合热升级）</td><td>master</td></tr><tr><td>CHLD</td><td>「你有个孩子退出了」（内核自动发的）</td><td>master</td></tr></tbody></table><p>最后那行 CHLD 是防线的地基。任何 worker 死掉，内核都会自动给 master 发 CHLD；master 收到就去收尸（拿到退出状态），然后补招新 worker——「崩了自动满血」靠的就是这条暗号，不需要任何轮询。</p><h2 id="reload-的时序推演-为什么下载不断" tabindex="-1">reload 的时序推演：为什么下载不断 <a class="header-anchor" href="#reload-的时序推演-为什么下载不断" aria-label="Permalink to &quot;reload 的时序推演：为什么下载不断&quot;">​</a></h2><p>现在把周五那个问题一行行推演出来。你敲 <code>nginx -s reload</code>，实际发生的是向 master 发 HUP，master 依次做六件事：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. master 收到 HUP</span></span>
<span class="line"><span>2. 重新读 nginx.conf —— 解析失败（比如第 6 章那种未闭合的块）？</span></span>
<span class="line"><span>   → 直接报错放弃，旧 worker 一个都不动，线上无感（这就是「先验配置再动手」的价值）</span></span>
<span class="line"><span>3. 用新配置 fork 一批新 worker —— 新 worker 出生时就带着新规则</span></span>
<span class="line"><span>4. 向所有旧 worker 发 QUIT</span></span>
<span class="line"><span>5. 旧 worker：从总机上摘掉自己（不再接新客），但手里已有的连接继续服务到底</span></span>
<span class="line"><span>6. 每个旧 worker 送完最后一个连接，退出；master 收尸</span></span></code></pre></div><p>正在下载的用户为什么不断线？他的连接在步骤 5 被旧 worker 捧在手里——QUIT 的语义不是「挂断」，是<strong>优雅关闭</strong>（graceful shutdown）——「不再接新客，把手头的客人送完再下班」。新客则从第一步换血开始就全部落到新 worker 手里，全程没有任何一条存量连接被掐。代价要说清：旧 worker 会一直活到最长的那个连接结束（长轮询、大下载），所以 reload 后你 <code>ps</code> 会短暂看到两代 worker 并存——这不是 bug，是优雅的账单。</p><p>热升级（换 nginx 二进制本身）是同一套把戏的极致版：USR2 让 master 启动新二进制的进程，新进程继承总机的钥匙，起自己的 worker；确认新版没问题后，WINCH 让旧 worker 优雅退休，最后 TERM 送走旧 master——换发动机，不熄火。</p><h2 id="tinysrv-为什么停在单进程" tabindex="-1">tinysrv 为什么停在单进程 <a class="header-anchor" href="#tinysrv-为什么停在单进程" aria-label="Permalink to &quot;tinysrv 为什么停在单进程&quot;">​</a></h2><p>公开说清楚边界：tinysrv 是单进程的（一个事件循环），没有实现这套模型——因为本课的教学焦点在单循环内部的机制，而进程编排属于另一层。但这一章你获得的是「读得懂」的能力：Node.js 的 <code>cluster</code> 模块就是这套架构的现成翻版——<code>cluster.fork()</code> 出的子进程默认共享同一个监听端口、由内核分发新连接，正是「总机 + 一队员工」。练习附录里给你留了一条用 cluster 把 tinysrv 变成多进程的路，机制你已经全懂了。</p><h2 id="读完本章-你该能回答" tabindex="-1">读完本章，你该能回答 <a class="header-anchor" href="#读完本章-你该能回答" aria-label="Permalink to &quot;读完本章，你该能回答&quot;">​</a></h2><ul><li>多进程抹掉了多线程的哪两笔账？worker 数量跟什么走、跟什么不走？</li><li>监听 socket 为什么在 master 手里创建？worker 崩了整站为什么还活着，哪条信号是地基？</li><li>reload 的六步时序里，正在下载的连接在哪一步被保护？代价是什么？</li><li>惊群是什么？现代方案的一句话结论是什么？</li></ul><p>第二部分到此完成：内存怎么还（池）、规则怎么定（配置）、进程怎么分层（master-worker）。第三部分进入 nginx 的主场——流量：反向代理、负载均衡、限流。</p>`,27)])])}const h=e(n,[["render",o]]);export{w as __pageData,h as default};
